// Function to print packet information
void print_packet_info(const u_char *packet_data, int packet_length) {
    struct iphdr *ip_header = (struct iphdr *)packet_data;
    struct tcphdr *tcp_header = (struct tcphdr *)(packet_data + ip_header->ihl * 4);

    printf("Source IP: %s\n", inet_ntoa(ip_header->saddr));
    printf("Destination IP: %s\n", inet_ntoa(ip_header->daddr));
    printf("Source Port: %d\n", ntohs(tcp_header->source));
    printf("Destination Port: %d\n", ntohs(tcp_header->dest));
    printf("Protocol: %d\n", ip_header->protocol);
    printf("Length: %d\n", ip_header->tot_len);
    printf("Flags: %d\n", tcp_header->flags);
    printf("Sequence Number: %d\n", ntohl(tcp_header->seq));
    printf("Acknowledgment Number: %d\n", ntohl(tcp_header->ack_seq));
    printf("Window Size: %d\n", ntohs(tcp_header->window));
    printf("Checksum: %d\n", ntohs(tcp_header->check));
    printf("Options: %d\n", tcp_header->options);
    printf("\n");
}

// Function to check for potential threats
int check_for_threats(const u_char *packet_data, int packet_length) {
    struct iphdr *ip_header = (struct iphdr *)packet_data;
    struct tcphdr *tcp_header = (struct tcphdr *)(packet_data + ip_header->ihl * 4);

    // Check for suspicious ports
    if (ntohs(tcp_header->source) == 25 || ntohs(tcp_header->dest) == 25) {
        return 1;
    }

    // Check for suspicious protocols
    if (ip_header->protocol == IPPROTO_TCP) {
        return 1;
    }

    return 0;
}

