// Function to check if a user is authorized
int is_user_authorized(const char* username, const char* password) {
    // Replace this with your actual authorization logic
    // For example, you could check against a file or database
    if (strcmp(username, "admin") == 0 && strcmp(password, "password123") == 0) {
        return 1;
    }
    return 0;
}

// Function to log access attempts
void log_access_attempt(const char* username, int success) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_file, "%s: %s\n", username, success ? "SUCCESS" : "FAILED");
    fclose(log_file);
}

// Function to check if a user has access to the directory
int check_directory_access(const char* username, const char* password) {
    if (is_user_authorized(username, password)) {
        log_access_attempt(username, 1);
        return 1;
    } else {
        log_access_attempt(username, 0);
        return 0;
    }
}

// Main function
int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <username> <password>\n", argv[0]);
        return 1;
    }

    const char* username = argv[1];
    const char* password = argv[2];

    if (check_directory_access(username, password)) {
        printf("Access granted.\n");
    } else {
        printf("Access denied.\n");
    }

    return 0;
}

