// Function to check if an IP address is in the whitelist
int is_whitelisted(char* ip) {
    FILE* fp = fopen(WHITELIST_FILE, "r");
    if (!fp) {
        return 0;
    }
    char line[100];
    while (fgets(line, sizeof(line), fp)) {
        if (strstr(line, ip) != NULL) {
            fclose(fp);
            return 1;
        }
    }
    fclose(fp);
    return 0;
}

// Function to check if an IP address is suspicious based on the threshold
int is_suspicious(char* ip) {
    int suspicious_count = 0;
    FILE* fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        return 0;
    }
    char line[100];
    while (fgets(line, sizeof(line), fp)) {
        if (strstr(line, ip) != NULL) {
            suspicious_count++;
        }
    }
    fclose(fp);
    return suspicious_count >= THRESHOLD;
}

