// Function to count unique IP addresses in a list
int countUniqueIPs(char *ipList[], int numIPs) {
    int uniqueCount = 0;
    char *currentIP = NULL;
    char *nextIP = NULL;

    for (int i = 0; i < numIPs; i++) {
        currentIP = ipList[i];
        nextIP = NULL;

        // Check if the current IP address is already in the list
        for (int j = 0; j < i; j++) {
            if (strcmp(ipList[j], currentIP) == 0) {
                nextIP = ipList[j];
                break;
            }
        }

        // If the current IP address is not in the list, increment the unique count
        if (nextIP == NULL) {
            uniqueCount++;
        }
    }

    return uniqueCount;
}

// Function to write firewall rules for a list of IP addresses
void writeFirewallRules(char *ipList[], int numIPs, char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        printf("Error opening file for writing.\n");
        exit(1);
    }

    for (int i = 0; i < numIPs; i++) {
        fprintf(file, "iptables -A INPUT -s %s -j DROP\n", ipList[i]);
    }

    fclose(file);
    printf("Firewall rules written to %s.\n", filename);
}

