// Function to check if an IP address is in a CIDR range
int is_in_cidr(char *ip, char *cidr) {
    struct in_addr addr;
    struct in_addr cidr_addr;
    int prefix_len;
    int i;

    // Convert IP address to network byte order
    inet_aton(ip, &addr);
    inet_aton(cidr, &cidr_addr);

    // Extract prefix length from CIDR notation
    prefix_len = 0;
    for (i = 0; cidr[i] != '\0'; i++) {
        if (cidr[i] == '/') {
            prefix_len = atoi(cidr + i + 1);
            break;
        }
    }

    // Check if IP address is in the CIDR range
    if (prefix_len == 0) {
        return 0;
    }

    // Convert CIDR address to network byte order
    struct in_addr cidr_net;
    cidr_net.s_addr = cidr_addr.s_addr & htonl(0xFFFFFFFFUL << (32 - prefix_len));

    // Check if IP address is in the CIDR range
    if ((addr.s_addr & htonl(0xFFFFFFFFUL << (32 - prefix_len))) == cidr_net.s_addr) {
        return 1;
    }

    return 0;
}

// Function to check if an IP address is in a whitelist
int is_in_whitelist(char *ip, char *whitelist) {
    char *token;
    char *whitelist_copy = strdup(whitelist);
    int i;

    // Split whitelist by commas
    token = strtok(whitelist_copy, ",");
    while (token != NULL) {
        // Check if IP address is in the whitelist
        if (strcmp(token, ip) == 0) {
            free(whitelist_copy);
            return 1;
        }
        token = strtok(NULL, ",");
    }

    free(whitelist_copy);
    return 0;
}

