// Function to block access to the directory
void block_directory_access(char *directory_path) {
    // Open the directory in read-only mode
    int fd = open(directory_path, O_RDONLY);
    if (fd == -1) {
        perror("Error opening directory");
        exit(EXIT_FAILURE);
    }

    // Create a temporary file to store the blocked status
    char temp_file[256];
    snprintf(temp_file, sizeof(temp_file), "%s.blocked", directory_path);

    // Write the blocked status to the temporary file
    int temp_fd = open(temp_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (temp_fd == -1) {
        perror("Error creating temporary file");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Write "blocked" to the temporary file
    write(temp_fd, "blocked", 7);

    // Close the temporary file
    close(temp_fd);

    // Close the directory file descriptor
    close(fd);

    // Remove the temporary file
    unlink(temp_file);
}

// Function to unblock access to the directory
void unblock_directory_access(char *directory_path) {
    // Create a temporary file to store the unblocked status
    char temp_file[256];
    snprintf(temp_file, sizeof(temp_file), "%s.unblocked", directory_path);

    // Write the unblocked status to the temporary file
    int temp_fd = open(temp_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (temp_fd == -1) {
        perror("Error creating temporary file");
        exit(EXIT_FAILURE);
    }

    // Write "unblocked" to the temporary file
    write(temp_fd, "unblocked", 9);

    // Close the temporary file
    close(temp_fd);

    // Remove the temporary file
    unlink(temp_file);
}

