// Function to check if an IP address is within a CIDR range
int is_ip_in_cidr(char *ip_str, char *cidr_str) {
    struct in_addr ip_addr;
    struct in_addr cidr_addr;
    int cidr_len;
    int ip_len;
    int i;
    int result = 0;

    // Convert IP address string to network byte order
    if (inet_aton(ip_str, &ip_addr) == 0) {
        return 0;
    }

    // Convert CIDR string to network byte order
    if (inet_aton(cidr_str, &cidr_addr) == 0) {
        return 0;
    }

    // Extract CIDR length from CIDR string
    cidr_len = 0;
    for (i = 0; cidr_str[i] != '\0'; i++) {
        if (cidr_str[i] == '/') {
            cidr_len = i;
            break;
        }
    }

    // Convert CIDR length to mask
    unsigned long mask = 0;
    for (i = 0; i < cidr_len; i++) {
        mask |= (1UL << (32 - i - 1));
    }

    // Check if IP address is within CIDR range
    if ((ip_addr.s_addr & mask) == (cidr_addr.s_addr & mask)) {
        result = 1;
    }

    return result;
}

