// Function to check if a user has the required privileges
int has_privileges() {
    struct passwd *pw;
    struct group *gr;
    char *user = getenv("USER");
    char *group = getenv("GROUP");

    pw = getpwnam(user);
    if (!pw) {
        return 0;
    }

    gr = getgrnam(group);
    if (!gr) {
        return 0;
    }

    // Check if the user has the required privileges
    if (pw->pw_uid == 0 || gr->gr_gid == 0) {
        return 1;
    }

    return 0;
}

// Function to create a temporary directory
int create_temp_dir(char *dir_path) {
    int result = mkdir(dir_path, 0755);
    if (result == -1) {
        perror("Error creating temporary directory");
        return 0;
    }

    return 1;
}

