// Function to check if a user is in a specific group
int is_user_in_group(const char *username, const char *groupname) {
    struct passwd *pwd;
    struct group *grp;
    char *token;
    char *group_list;

    pwd = getpwnam(username);
    if (!pwd) return 0;

    group_list = getgrnam(groupname);
    if (!group_list) return 0;

    token = strtok(group_list->gr_mem, ",");
    while (token) {
        if (strcmp(token, username) == 0) {
            return 1;
        }
        token = strtok(NULL, ",");
    }

    return 0;
}

// Function to check if a user has write access to a directory
int has_write_access(const char *username, const char *directory) {
    struct passwd *pwd;
    struct stat st;
    char *token;
    char *group_list;

    pwd = getpwnam(username);
    if (!pwd) return 0;

    group_list = getgrnam(pwd->pw_gid);
    if (!group_list) return 0;

    token = strtok(group_list->gr_mem, ",");
    while (token) {
        if (strcmp(token, username) == 0) {
            return 1;
        }
        token = strtok(NULL, ",");
    }

    return 0;
}

// Function to log access attempts
void log_access_attempt(const char *username, const char *directory, int success) {
    FILE *fp;
    time_t t;
    char buffer[MAX_PATH];

    fp = fopen(LOG_FILE, "a");
    if (!fp) return;

    t = time(NULL);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&t));
    fprintf(fp, "%s %s %s %s\n", buffer, username, directory, success ? "SUCCESS" : "FAILED");
    fclose(fp);
}

