// Function to check if a file is executable
int is_executable(const char *path) {
    struct stat sb;
    if (stat(path, &sb) == -1) {
        return 0;
    }
    return (sb.st_mode & S_IXUSR) || (sb.st_mode & S_IXGRP) || (sb.st_mode & S_IXOTH);
}

