// Structure to represent a rule
typedef struct {
    char src_ip[INET_ADDRSTRLEN];
    char dst_ip[INET_ADDRSTRLEN];
    int src_port;
    int dst_port;
    int packet_length;
    int action; // 0 for allow, 1 for block
} Rule;

// Function to parse a rule string into a Rule structure
int parse_rule(const char* rule_str, Rule* rule) {
    char* token;
    char* temp_str = strdup(rule_str);
    char* delimiter = " ";
    int action = 0;

    // Parse source IP address
    token = strtok(temp_str, delimiter);
    if (token == NULL) {
        free(temp_str);
        return -1;
    }
    strcpy(rule->src_ip, token);

    // Parse destination IP address
    token = strtok(NULL, delimiter);
    if (token == NULL) {
        free(temp_str);
        return -1;
    }
    strcpy(rule->dst_ip, token);

    // Parse source port
    token = strtok(NULL, delimiter);
    if (token == NULL) {
        free(temp_str);
        return -1;
    }
    rule->src_port = atoi(token);

    // Parse destination port
    token = strtok(NULL, delimiter);
    if (token == NULL) {
        free(temp_str);
        return -1;
    }
    rule->dst_port = atoi(token);

    // Parse packet length
    token = strtok(NULL, delimiter);
    if (token == NULL) {
        free(temp_str);
        return -1;
    }
    rule->packet_length = atoi(token);

    // Parse action
    token = strtok(NULL, delimiter);
    if (token == NULL) {
        free(temp_str);
        return -1;
    }
    if (strcmp(token, "block") == 0) {
        action = 1;
    }

    free(temp_str);
    return action;
}

