    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)password, NULL);

    unsigned char *buffer = malloc(1024);
    int buffer_size = 1024;
    int bytes_written = 0;

    while (!feof(fp)) {
        int bytes_read = fread(buffer, 1, buffer_size, fp);
        if (bytes_read == 0) break;

        EVP_EncryptUpdate(ctx, buffer, &bytes_written, buffer, bytes_read);
        fwrite(buffer, 1, bytes_written, stdout);
    }

    EVP_EncryptFinal_ex(ctx, buffer, &bytes_written);
    fwrite(buffer, 1, bytes_written, stdout);

    EVP_CIPHER_CTX_free(ctx);
    free(buffer);
    fclose(fp);

    return 0;
}

