// Function to check if an IP address is in a given CIDR range
int is_in_cidr(char *ip, char *cidr) {
    struct in_addr addr;
    struct in_addr cidr_addr;
    int prefix_len;
    int i;

    // Convert IP address to network byte order
    if (inet_aton(ip, &addr) == 0) {
        return 0;
    }

    // Convert CIDR range to network byte order
    if (inet_aton(cidr, &cidr_addr) == 0) {
        return 0;
    }

    // Extract prefix length from CIDR notation
    prefix_len = 0;
    for (i = 0; cidr[i] != '\0'; i++) {
        if (cidr[i] == '/') {
            prefix_len = atoi(cidr + i + 1);
            break;
        }
    }

    // Check if IP address is in CIDR range
    if (prefix_len == 0) {
        return 0;
    }

    // Convert CIDR range to network byte order
    unsigned long long cidr_mask = 0xFFFFFFFFULL << (64 - prefix_len);
    unsigned long long addr_mask = 0xFFFFFFFFULL << (64 - prefix_len);

    // Check if IP address is in CIDR range
    if ((addr.s_addr & cidr_mask) == (cidr_addr.s_addr & cidr_mask)) {
        return 1;
    }

    return 0;
}

