// Function to retrieve the IP address of incoming traffic
char* get_ip_address() {
    char buffer[INET_ADDRSTRLEN];
    struct sockaddr_in addr;
    socklen_t len = sizeof(addr);
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }
    // Bind the socket to any available port
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(0);
    if (bind(sock, (struct sockaddr*)&addr, sizeof(addr)) == -1) {
        perror("bind");
        close(sock);
        exit(EXIT_FAILURE);
    }
    // Send a dummy packet to the socket and retrieve the source IP address
    sendto(sock, "", 0, 0, (struct sockaddr*)&addr, sizeof(addr));
    getsockname(sock, (struct sockaddr*)&addr, &len);
    inet_ntop(AF_INET, &addr.sin_addr, buffer, INET_ADDRSTRLEN);
    close(sock);
    return strdup(buffer);
}

