#define DIRECTORY "<home>/documents"
#define LOG_FILE "/var/log/access.log"

int main() {
    char username[256];
    struct passwd *pw;
    struct stat file_stat;
    int result;

    // Get the current user's username
    pw = getpwuid(getuid());
    if (pw == NULL) {
        perror("getpwuid");
        exit(EXIT_FAILURE);
    }
    strcpy(username, pw->pw_name);

    // Check if the user is allowed to access the directory
    result = stat(DIRECTORY, &file_stat);
    if (result == 0) {
        // The directory exists, check if the user has access
        if (file_stat.st_uid != getuid()) {
            // The user is not the owner of the directory
            fprintf(stderr, "Access denied: You do not have permission to access %s\n", DIRECTORY);
            exit(EXIT_FAILURE);
        }
    } else {
        // The directory does not exist
        fprintf(stderr, "Access denied: The directory %s does not exist\n", DIRECTORY);
        exit(EXIT_FAILURE);
    }

    // Log the access attempt
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s accessed %s at %s\n", username, DIRECTORY, ctime(&time(NULL)));
    fclose(log_file);

    // Allow access to the directory
    printf("Access granted to %s\n", DIRECTORY);
    return 0;
}

