    strcpy(config_file, "/etc/myapp.conf");
    strcpy(new_value, "1"); // Change this value to modify system behavior

    fp = fopen(config_file, "r");
    if (fp == NULL) {
        perror("Error opening configuration file");
        exit(EXIT_FAILURE);
    }

    while (fgets(line, sizeof(line), fp) != NULL) {
        if (strstr(line, "debug_mode") != NULL) {
            found = 1;
            break;
        }
    }

    fclose(fp);

    if (found) {
        fp = fopen(config_file, "w");
        if (fp == NULL) {
            perror("Error opening configuration file for writing");
