// Function to check if the current time is within the 24-hour window
int is_within_window(struct timeval *start_time) {
    struct timeval end_time;
    gettimeofday(&end_time, NULL);
    long diff = (end_time.tv_sec - start_time->tv_sec) * 1000 + (end_time.tv_usec - start_time->tv_usec) / 1000;
    return diff < 24 * 60 * 60; // 24 hours in milliseconds
}

// Main function
