    unsigned char old_key[32];
    unsigned char new_key[32];
    struct timeval start_time;
    gettimeofday(&start_time, NULL);

    // Generate a random key
    generate_key(old_key, 32);

    // Rotate the key every 24 hours
    while (1) {
        if (is_within_window(&start_time)) {
            rotate_key(old_key, new_key, 32);
            distribute_key(new_key, 32);
        }
        sleep(60); // Check every minute
    }

    return 0;
}

