// Function to check if an IP address is already blocked
int is_blocked(const char* ip) {
    for (int i = 0; i < blocked_count; i++) {
        if (strcmp(blocked_ips[i].ip, ip) == 0) {
            return 1;
        }
    }
    return 0;
}

// Function to block an IP address using iptables
void block_ip(const char* ip) {
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "iptables -A INPUT -s %s -j DROP", ip);
    system(cmd);
    syslog(LOG_INFO, "Blocked IP address: %s", ip);
}

// Function to log blocked IP addresses and failed login attempts
void log_blocked_ip(const char* ip, int failed_attempts) {
    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Blocked IP address %s after %d failed login attempts", ip, failed_attempts);
    syslog(LOG_INFO, log_msg);
}

// Function to check if an IP address is within the time window
int is_within_time_window(const char* ip, time_t current_time) {
    for (int i = 0; i < blocked_count; i++) {
        if (strcmp(blocked_ips[i].ip, ip) == 0) {
            if (current_time - blocked_ips[i].last_attempt < TIME_WINDOW) {
                return 1;
            }
        }
    }
    return 0;
}

