    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL);

    encrypted_data = malloc(file_size + 16);
    int len = 0;
    int decrypted_len = 0;

    EVP_EncryptUpdate(ctx, encrypted_data, &len, file_data, file_size);
    EVP_EncryptFinal_ex(ctx, encrypted_data + len, &decrypted_len);

