    socklen_t len = sizeof(addr);
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }
    // Send a dummy packet to any address and port
    sendto(sock, "", 0, 0, (struct sockaddr*)&addr, len);
    // Receive the response
    recvfrom(sock, buffer, INET_ADDRSTRLEN, 0, (struct sockaddr*)&addr, &len);
    close(sock);
    return strdup(buffer);
}

