// Function to perform DNS lookups on unknown hosts
void perform_dns_lookup(char *hostname) {
    struct hostent *host;
    char buffer[256];
    int status;

    status = gethostbyname(hostname);
    if (status == 0) {
        printf("DNS lookup failed for %s\n", hostname);
        return;
    }

    host = gethostbyname(hostname);
    strcpy(buffer, inet_ntoa(*((struct in_addr *)host->h_addr_list[0])));
    printf("DNS lookup successful: %s -> %s\n", hostname, buffer);
}

