// Function to parse network packets and identify suspicious patterns
int parse_packet(const char* packet, int packet_len) {
    regex_t regex;
    char* ip_addr;
    char* src_port;
    char* dst_port;
    char* protocol;
    char* payload;
    int src_port_int;
    int dst_port_int;
    int protocol_int;
    int suspicious = 0;

    // Extract IP address, source port, destination port, and protocol from the packet
    ip_addr = strstr(packet, "IP=");
    if (ip_addr == NULL) {
        return 0;
    }
    ip_addr += 3;
    src_port = strstr(ip_addr, "src=");
    if (src_port == NULL) {
        return 0;
    }
    src_port += 4;
    dst_port = strstr(src_port, "dst=");
    if (dst_port == NULL) {
        return 0;
    }
    dst_port += 4;
    protocol = strstr(dst_port, "proto=");
    if (protocol == NULL) {
        return 0;
    }
    protocol += 6;
    payload = strstr(protocol, "payload=");
    if (payload == NULL) {
        return 0;
    }
    payload += 8;

    // Convert source and destination ports to integers
    src_port_int = atoi(src_port);
    dst_port_int = atoi(dst_port);

    // Convert protocol to integer
    protocol_int = atoi(protocol);

    // Check for suspicious patterns
    if (src_port_int == 0 || dst_port_int == 0) {
        suspicious = 1;
    }
    if (protocol_int == 0) {
        suspicious = 1;
    }
    if (strstr(payload, "malicious") != NULL) {
        suspicious = 1;
    }

    return suspicious;
}

