        close(sock);
        exit(EXIT_FAILURE);
    }

    // Start traffic monitoring thread
    pthread_create(&tid, NULL, traffic_monitor, NULL);

    // Wait for threads to finish
    pthread_join(tid, NULL);

    // Close socket
    close(sock);

    return 0;
