// Function to count unique IP addresses in a list
int count_unique_ips(char **ips, int num_ips) {
    int count = 0;
    char **unique_ips = NULL;
    int unique_count = 0;

    for (int i = 0; i < num_ips; i++) {
        int found = 0;
        for (int j = 0; j < unique_count; j++) {
            if (strcmp(ips[i], unique_ips[j]) == 0) {
                found = 1;
                break;
            }
        }
        if (!found) {
            unique_ips = realloc(unique_ips, (unique_count + 1) * sizeof(char *));
            unique_ips[unique_count] = strdup(ips[i]);
            unique_count++;
        }
    }

    count = unique_count;
    free(unique_ips);
    return count;
}

// Function to write firewall rules for blocked IPs
void write_firewall_rules(char **ips, int num_ips) {
    int unique_count = count_unique_ips(ips, num_ips);
    char *ufw_rules = NULL;
    int ufw_rules_len = 0;

    for (int i = 0; i < num_ips; i++) {
        char *ip = ips[i];
        char *rule = NULL;
        int rule_len = 0;

        rule_len = snprintf(NULL, 0, "ufw deny from %s", ip);
        rule = malloc(rule_len + 1);
        snprintf(rule, rule_len + 1, "ufw deny from %s", ip);

        ufw_rules_len = snprintf(NULL, 0, "%s\n", ufw_rules);
        ufw_rules = realloc(ufw_rules, ufw_rules_len + 1);
        strcat(ufw_rules, rule);
    }

    FILE *file = fopen("/etc/ufw.rules", "w");
    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%s", ufw_rules);
    fclose(file);

    printf("Firewall rules written to /etc/ufw.rules\n");
}

