// Function to search for a configuration file in the current directory
char* find_config_file(char* filename) {
    DIR* dir = opendir(".");
    struct dirent* entry;
    char filepath[256];

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, filename) != NULL) {
            snprintf(filepath, sizeof(filepath), "%s/%s", ".", entry->d_name);
            closedir(dir);
            return filepath;
        }
    }

    closedir(dir);
    return NULL;
}

// Function to update the configuration file
int update_config_file(char* filepath, char* new_content) {
    FILE* file = fopen(filepath, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filepath);
        return -1;
    }

    char* buffer = malloc(1024);
    size_t size = fread(buffer, 1, 1024, file);
    fclose(file);

    // Replace the content with new_content
    strcpy(buffer, new_content);

    // Write the updated content back to the file
    file = fopen(filepath, "w");
    if (file == NULL) {
        printf("Error writing to file: %s\n", filepath);
        free(buffer);
        return -1;
    }

    fwrite(buffer, 1, size, file);
    fclose(file);

    free(buffer);
    return 0;
}

int main() {
    char* config_file = find_config_file("config.txt");
    if (config_file == NULL) {
        printf("Configuration file not found.\n");
        return -1;
    }

    char new_content[] = "Updated configuration file content.\n";
    update_config_file(config_file, new_content);

    printf("Configuration file updated successfully.\n");
    return 0;
}

