        return 1;
    }
    return 0;
}

// Function to check if the current user has the required permissions
int has_required_permissions(const char *directory) {
    struct stat file_stat;
    if (stat(directory, &file_stat) == -1) {
        return 0;
    }
    // Check if the user has read and write permissions
    if ((file_stat.st_mode & S_IRUSR) == 0 || (file_stat.st_mode & S_IWUSR) == 0) {
        return 0;
    }
    return 1;
}

// Function to check if the current user is in a predefined list of allowed groups
int is_group_allowed(const char *groupname, const char *directory) {
    struct group *group_info;
    group_info = getgrnam(groupname);
    if (group_info == NULL) {
        return 0;
    }
    // Check if the user is in the allowed group
    if (getgid() == group_info->gr_gid) {
        return 1;
    }
    return 0;
}

// Function to check if the current user is allowed to access the directory
int is_access_allowed(const char *directory) {
    char username[256];
    getlogin(username);
    // Check if the user is allowed to access the directory
    if (is_user_allowed(username, directory)) {
        return 1;
    }
    // Check if the user has the required permissions
    if (has_required_permissions(directory)) {
        return 1;
    }
    // Check if the user is in a predefined list of allowed groups
    if (is_group_allowed("allowed_group", directory)) {
        return 1;
    }
    return 0;
}

