// Function to encrypt data using the current key
int encrypt_data(const unsigned char *plaintext, unsigned char *ciphertext, int plaintext_len, unsigned char *key) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL);

    ciphertext_len = 0;
    EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &len);

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// Function to decrypt data using the current key
int decrypt_data(const unsigned char *ciphertext, unsigned char *plaintext, int ciphertext_len, unsigned char *key) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL);

    plaintext_len = 0;
    EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &len);

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

// Function to check if the key needs to be rotated
int needs_rotation(time_t current_time, time_t last_rotation_time) {
    return (current_time - last_rotation_time) >= 24 * 60 * 60;
}

