    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, key.c_str(), nullptr);
    unsigned char* decryptedData = nullptr;
    int decryptedSize = 0;
    EVP_DecryptUpdate(ctx, decryptedData, decryptedSize, (unsigned char*)encryptedData.c_str(), encryptedData.size());
    EVP_CIPHER_CTX_free(ctx);
    std::string result(reinterpret_cast<char*>(decryptedData), decryptedSize);
    return result;
}

