// Function to check if a user has access to a directory
bool hasAccess(const std::string& username, const std::string& directory) {
    struct passwd* pwd = getpwnam(username.c_str());
    if (!pwd) return false;

    struct stat fileStat;
    if (stat(directory.c_str(), &fileStat) != 0) return false;

    // Check if the user has read/write/execute permissions
    return (fileStat.st_uid == pwd->pw_uid || 
            (fileStat.st_mode & S_IRUSR) || 
            (fileStat.st_mode & S_IWUSR) || 
            (fileStat.st_mode & S_IXUSR));
}

// Function to block access to a directory for a specific user
void blockAccess(const std::string& username, const std::string& directory) {
    std::string logFile = "/var/log/directory_access.log";
    std::ofstream logStream(logFile, std::ios::app);
    if (!logStream.is_open()) {
        std::cerr << "Error opening log file for writing." << std::endl;
        return;
    }

    // Set the directory permissions to deny access for the specified user
    struct stat fileStat;
    if (stat(directory.c_str(), &fileStat) != 0) {
