Here is an example of how to implement a simple access control system in C++:

```cpp
#include <iostream>
#include <sys/stat.h>
#include <unistd.h>
#include <pwd.h>
#include <grp.h>
#include <string>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>

// Function to check if a user has access to a directory
bool hasAccess(const std::string& directory, const std::string& username) {
    struct stat fileStat;
    if (stat(directory.c_str(), &fileStat) != 0) {
        return false;
    }

    // Check if the user is in the group that owns the directory
    struct passwd* pwd = getpwuid(getuid());
    struct group* grp = getgrgid(fileStat.st_gid);
    if (pwd && grp && std::string(pwd->pw_name) == username && std::string(grp->gr_name) == std::string(pwd->pw_name)) {
        return true;
    }

    // Check if the user has write permissions on the directory
    if (fileStat.st_mode & S_IWUSR) {
        return true;
    }

    return false;
}

// Function to log access attempts
void logAccessAttempt(const std::string& directory, const std::string& username, bool success) {
    std::ofstream logFile("/var/log/directory_access.log", std::ios::app);
    if (logFile.is_open()) {
        logFile << "[" << std::ctime(&std::time(nullptr)) << "] " << username << " " << (success ? "SUCCESS" : "FAILURE") << " access to " << directory << std::endl;
        logFile.close();
    }
}

// Main function
int main() {
    std::string directory = "/path/to/protected/directory";
    std::string username = "current_user";

    if (hasAccess(directory, username)) {
        std::cout << "Access granted." << std::endl;
    } else {
        logAccessAttempt(directory, username, false);
        std::cout << "Access denied." << std::endl;
    }

    return 0;
}
