using namespace std;

// Global variables
vector<string> trusted_ips;
set<string> blocked_ips;
mutex mtx;
bool emergency_mode = false;

// Function to check if an IP address is trusted
bool is_trusted_ip(const string& ip) {
    for (const auto& trusted_ip : trusted_ips) {
        if (ip == trusted_ip) {
            return true;
        }
    }
    return false;
}

// Function to block an IP address
void block_ip(const string& ip) {
    mtx.lock();
    blocked_ips.insert(ip);
    mtx.unlock();
    cout << "Blocked IP address: " << ip << endl;
}

// Function to unblock an IP address
void unblock_ip(const string& ip) {
    mtx.lock();
    blocked_ips.erase(ip);
    mtx.unlock();
    cout << "Unblocked IP address: " << ip << endl;
}

// Function to check if an IP address is blocked
bool is_blocked_ip(const string& ip) {
    mtx.lock();
    if (blocked_ips.find(ip) != blocked_ips.end()) {
        mtx.unlock();
        return true;
    }
    mtx.unlock();
    return false;
}

// Function to print the list of blocked IP addresses
void print_blocked_ips() {
    mtx.lock();
    cout << "Blocked IP addresses:" << endl;
    for (const auto& blocked_ip : blocked_ips) {
        cout << blocked_ip << endl;
    }
    mtx.unlock();
}

// Function to handle emergency mode
void handle_emergency_mode() {
    cout << "Emergency mode activated!" << endl;
    emergency_mode = true;
    print_blocked_ips();
}

// Function to handle normal mode
void handle_normal_mode() {
    cout << "Normal mode activated!" << endl;
    emergency_mode = false;
    print_blocked_ips();
}

// Function to check if an IP address is allowed
bool is_allowed_ip(const string& ip) {
    if (emergency_mode) {
        return true;
    }
    return is_trusted_ip(ip);
