int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    char *dir = argv[1];
    struct stat st;

    if (stat(dir, &st) == -1) {
        perror("stat");
        exit(EXIT_FAILURE);
    }

    if (S_ISDIR(st.st_mode)) {
        // Directory exists, attempt to block access
        int fd = open(dir, O_RDONLY);
        if (fd != -1) {
            close(fd);
            printf("Access to directory %s blocked.\n", dir);
        } else {
            perror("open");
            exit(EXIT_FAILURE);
        }
    } else {
        fprintf(stderr, "%s is not a directory.\n", dir);
        exit(EXIT_FAILURE);
    }

    return 0;
}

