using namespace std;

// Function to count unique IP addresses in a list
int countUniqueIPs(const vector<string>& ips) {
    set<string> uniqueIps;
    for (const string& ip : ips) {
        uniqueIps.insert(ip);
    }
    return uniqueIps.size();
}

// Function to write firewall rules for blocked IPs
void writeFirewallRules(const vector<string>& blockedIPs) {
    ofstream rulesFile("/etc/ufw/rules");
    if (!rulesFile.is_open()) {
        cerr << "Error: Could not open /etc/ufw/rules for writing." << endl;
        return;
    }

    for (const string& ip : blockedIPs) {
        rulesFile << "ufw deny from " << ip << endl;
    }

    rulesFile.close();
    cout << "Firewall rules written successfully to /etc/ufw/rules." << endl;
}

// Function to read IP addresses from a file
vector<string> readIPsFromFile(const string& filename) {
    vector<string> ips;
    ifstream file(filename);
    string line;

    while (getline(file, line)) {
        // Remove any leading/trailing whitespace
        line.erase(0, line.find_first_not_of(" \t\n\r\f\v"));
        line.erase(line.find_last_not_of(" \t\n\r\f\v") + 1);

        // Check if the line is not empty and contains only IP addresses
        if (!line.empty() && line.find_first_not_of("0123456789.") == string::npos) {
            ips.push_back(line);
        }
    }

    return ips;
}

// Main function
int main() {
    vector<string> blockedIPs;

    // Read IP addresses from a file
    string filename = "blocked_ips.txt";
    vector<string> ips = readIPsFromFile(filename);

    // Count unique IP addresses
    int uniqueCount = countUniqueIPs(ips);
    cout << "Number of unique IP addresses: " << uniqueCount << endl;

    // Write firewall rules for blocked IPs
    writeFirewallRules(ips);

    return 0;
}

