using namespace std;

// Function to search for a file by name in the current directory and subdirectories
vector<string> searchFile(const string& filename) {
    vector<string> results;
    for (const auto& entry : filesystem::recursive_directory_iterator(".")) {
        if (entry.is_regular_file() && entry.path().filename() == filename) {
            results.push_back(entry.path().string());
        }
    }
    return results;
}

// Function to update a configuration file without overwriting the original file
bool updateConfigFile(const string& filepath, const string& newContent) {
    ifstream file(filepath);
    if (!file.is_open()) {
        cerr << "Error: Could not open file for reading: " << filepath << endl;
        return false;
    }

    string content((istreambuf_iterator<char>(file)), istreambuf_iterator<char>());
    file.close();

    // Replace the old content with the new content
    ofstream tempFile(filepath + ".tmp");
    if (!tempFile.is_open()) {
        cerr << "Error: Could not open file for writing: " << filepath << endl;
        return false;
    }

    tempFile << newContent;
    tempFile.close();

    // Replace the original file with the temporary file
    if (filesystem::exists(filepath)) {
        filesystem::remove(filepath);
    }

    if (!filesystem::rename(filepath + ".tmp", filepath)) {
        cerr << "Error: Could not rename temporary file to original file: " << filepath << endl;
        return false;
    }

    return true;
}

// Main function
int main() {
    string filename = "config.txt";
    string newContent = "Updated configuration file content";

    // Search for the file
    vector<string> results = searchFile(filename);
    if (results.empty()) {
        cerr << "Error: File not found: " << filename << endl;
        return 1;
    }

    // Update the configuration file
    for (const auto& filepath : results) {
        if (updateConfigFile(filepath, newContent)) {
            cout << "Configuration file updated successfully: " << filepath << endl;
        } else {
            cerr << "Error: Failed to update configuration file: " << filepath << endl;
        }
    }

    return 0;
}

