#include <string>
#include <vector>
#include <sstream>
#include <regex>

using namespace std;

// Function to check if a string is an IP address
bool isValidIP(const string& ip) {
    regex ipRegex("^((25[0-5]|(2[0-4]|1\\d|[1-9])\\d)\\.){3}(25[0-5]|(2[0-4]|1\\d|[1-9])\\d)$");
    return regex_match(ip, ipRegex);
}

// Function to write a firewall rule to /etc/ufw/rules.v4
void writeFirewallRule(const string& ip) {
    ofstream file("/etc/ufw/rules.v4", ios::app);
    if (!file.is_open()) {
        cerr << "Error opening /etc/ufw/rules.v4 for writing." << endl;
        return;
    }

    file << "ufw allow from " << ip << " to any port 80,443" << endl;
    file << "ufw deny from " << ip << " to any" << endl;
    file.close();
}

// Function to log an error to /var/log/ufw.log
void logError(const string& error) {
    ofstream file("/var/log/ufw.log", ios::app);
    if (!file.is_open()) {
        cerr << "Error opening /var/log/ufw.log for writing." << endl;
        return;
    }

    file << "[" << string(20, '-') << "]" << " Error: " << error << endl;
    file.close();
}

// Function to parse input and write firewall rules
void parseInput(const vector<string>& ips) {
    for (const string& ip : ips) {
        if (isValidIP(ip)) {
            writeFirewallRule(ip);
        } else {
            logError("Invalid IP address: " + ip);
        }
    }
}

int main() {
    vector<string> ipAddresses;
    string line;

    // Read input from stdin
    while (getline(cin, line)) {
        if (line.empty()) {
            break;
        }
        ipAddresses.push_back(line);
    }

    // Parse input and write firewall rules
    parseInput(ipAddresses);

    return 0;
}

