using namespace std;

// Block list file path
const string BLOCK_LIST_FILE = "block_list.txt";

// Mutex for thread safety
mutex block_list_mutex;

// Function to update block list from trusted source
void updateBlockList() {
    ifstream trusted_source("trusted_source.txt");
    vector<string> new_block_list;
    string line;

    while (getline(trusted_source, line)) {
        if (!line.empty()) {
            new_block_list.push_back(line);
        }
    }

    // Update block list file
    ofstream block_list_file(BLOCK_LIST_FILE);
    for (const auto& ip : new_block_list) {
        block_list_file << ip << endl;
    }
    block_list_file.close();

    cout << "Block list updated successfully." << endl;
}

// Function to check if IP address is blocked
bool isBlocked(const string& ip) {
    ifstream block_list_file(BLOCK_LIST_FILE);
    string line;

    while (getline(block_list_file, line)) {
        if (line == ip) {
            return true;
        }
    }

    return false;
}

// Function to log access attempt
void logAccessAttempt(const string& ip, const string& action) {
    ofstream log_file("access_log.txt", ios::app);
    log_file << "[" << chrono::system_clock::now().time_since_epoch().count() << "] " << ip << " - " << action << endl;
    log_file.close();
}

// Main function
int main() {
    // Update block list every hour
    while (true) {
        updateBlockList();
        this_thread::sleep_for(chrono::hours(1));
    }

    return 0;
}

