class NetworkTrafficMonitor {
public:
    struct Rule {
        std::string src_ip;
        std::string dst_ip;
        int port;
        std::string protocol;
        std::string action; // "block" or "allow"
    };

    std::vector<Rule> rules;
    std::mutex rules_mutex;
    std::function<void()> alert_callback;

    void updateRules(const std::vector<Rule>& new_rules) {
        std::lock_guard<std::mutex> lock(rules_mutex);
        rules = new_rules;
    }

    void setAlertCallback(std::function<void()> callback) {
        alert_callback = callback;
    }

    void monitorTraffic() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(5));
            std::lock_guard<std::mutex> lock(rules_mutex);
            for (const auto& rule : rules) {
                if (isSuspicious(rule)) {
                    alert_callback();
                }
            }
        }
    }

private:
    bool isSuspicious(const Rule& rule) {
        // Placeholder logic for checking suspicious traffic
        return rule.action == "block";
    }
};

int main() {
    NetworkTrafficMonitor monitor;
    monitor.setAlertCallback([]() {
        std::cout << "ALERT: Suspicious traffic detected!" << std::endl;
    });

    std::vector<NetworkTrafficMonitor::Rule> rules = {
        {"<ip-address>", "<ip-address>", 80, "TCP", "block"}
    };

    monitor.updateRules(rules);

    std::thread monitor_thread(&NetworkTrafficMonitor::monitorTraffic, &monitor);
    monitor_thread.join();

    return 0;
}

