// Function to check if a user is authorized to access the repository
bool isAuthorized(const std::string& username, const std::string& password) {
    // Get the current environment variables
    char* env_username = getenv("USERNAME");
    char* env_password = getenv("PASSWORD");

    // Check if the environment variables are set
    if (env_username == nullptr || env_password == nullptr) {
        return false;
    }

    // Compare the provided username and password with the environment variables
    if (username == std::string(env_username) && password == std::string(env_password)) {
        return true;
    }

    // Check if the user is in the authorized users file
    std::ifstream authorized_users("authorized_users.txt");
    std::string line;
    while (std::getline(authorized_users, line)) {
        if (line == username) {
            authorized_users.close();
            return true;
        }
    }
    authorized_users.close();

    // If the user is not in the authorized users file, check if they are in the authorized passwords file
    std::ifstream authorized_passwords("authorized_passwords.txt");
    while (std::getline(authorized_passwords, line)) {
        if (line == password) {
            authorized_passwords.close();
            return true;
        }
    }
    authorized_passwords.close();

    // If the user is not in either file, they are not authorized
    return false;
}

// Main function to demonstrate how to use the authorization function
int main() {
    std::string username, password;

    std::cout << "Enter your username: ";
    std::cin >> username;

    std::cout << "Enter your password: ";
    std::cin >> password;

    if (isAuthorized(username, password)) {
        std::cout << "You are authorized to access the repository." << std::endl;
    } else {
        std::cout << "You are not authorized to access the repository." << std::endl;
    }

    return 0;
}

