// Function to block an IP address
void blockIP(const std::string& ip) {
    std::string cmd = "iptables -A INPUT -s " + ip + " -j DROP";
    system(cmd.c_str());
}

// Function to log blocked IP addresses
void logBlockedIP(const std::string& ip, const std::string& time) {
    std::ofstream logFile("blocked_ips.log", std::ios::app);
    if (logFile.is_open()) {
        logFile << time << " - Blocked IP: " << ip << std::endl;
        logFile.close();
    }
}

// Function to parse input file and block IPs
void parseAndBlockIPs(const std::string& inputFile) {
    std::ifstream inputFileStream(inputFile);
    std::string line;
    std::vector<std::string> blockedIPs;

    while (std::getline(inputFileStream, line)) {
        std::istringstream iss(line);
        std::string ip;
        if (std::getline(iss, ip, ' ')) {
            blockedIPs.push_back(ip);
        }
    }

    for (const auto& ip : blockedIPs) {
        blockIP(ip);
        std::string time = std::to_string(std::time(nullptr));
        logBlockedIP(ip, time);
    }
}

int main() {
    std::string inputFile = "ddos_ips.txt"; // Replace with your input file path
    parseAndBlockIPs(inputFile);
    std::cout << "DDoS attack IPs blocked successfully!" << std::endl;
    return 0;
}

#include <iostream>
#include <fstream>
