using namespace std;

// Function to check if the user is authorized to access the directory
bool isAuthorized(const string& username, const string& directory) {
    // Check if the user is in the authorized list
    ifstream authorizedFile("/etc/authorized_users");
    string line;
    while (getline(authorizedFile, line)) {
        if (line == username) {
            return true;
        }
    }
    return false;
}

// Function to log access attempts
void logAccessAttempt(const string& username, const string& directory, bool success) {
    ofstream logFile("/var/log/directory_access.log", ios::app);
    logFile << "[" << string(20, '-') << "]" << endl;
    logFile << "User: " << username << endl;
    logFile << "Directory: " << directory << endl;
    logFile << "Access: " << (success ? "Success" : "Failed") << endl;
    logFile << "[" << string(20, '-') << "]" << endl;
    logFile.close();
}

// Function to block access to the directory
void blockAccess(const string& directory) {
    // Check if the user is authorized to access the directory
    struct passwd* pwd = getpwuid(getuid());
    string username(pwd->pw_name);
    if (!isAuthorized(username, directory)) {
        logAccessAttempt(username, directory, false);
        exit(1);
    }
    // Allow access to the directory
    logAccessAttempt(username, directory, true);
}

// Main function
int main(int argc, char* argv[]) {
    // Check if the directory argument is provided
    if (argc != 2) {
        cerr << "Usage: " << argv[0] << " <directory>" << endl;
        return 1;
    }
    // Block access to the directory
    blockAccess(argv[1]);
    return 0;
}

