// Function to check if a string contains SQL injection patterns
bool isSqlInjection(string input) {
    // This is a simplified example; in practice, you would use a more comprehensive list of SQL injection patterns
    if (input.find("UNION") != string::npos || input.find("SELECT") != string::npos || input.find("INSERT") != string::npos) {
        return true;
    }
    return false;
}

// Function to log suspicious activity
void logActivity(string message) {
    syslog(LOG_INFO, "SQL Injection Detection: %s", message.c_str());
}

// Function to execute a parameterized query using prepared statements
bool executeQuery(sqlite3* db, const string& query, const vector<string>& parameters) {
    sqlite3_stmt* stmt;
    int rc;

    // Prepare the statement
    rc = sqlite3_prepare_v2(db, query.c_str(), -1, &stmt, nullptr);
    if (rc != SQLITE_OK) {
        logActivity("Failed to prepare statement: " + string(sqlite3_errmsg(db)));
        return false;
    }

    // Bind parameters
    for (size_t i = 0; i < parameters.size(); ++i) {
        rc = sqlite3_bind_text(stmt, i + 1, parameters[i].c_str(), -1, SQLITE_STATIC);
        if (rc != SQLITE_OK) {
            logActivity("Failed to bind parameter: " + string(sqlite3_errmsg(db)));
            sqlite3_finalize(stmt);
            return false;
        }
    }

    // Execute the statement
    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        logActivity("Error executing query: " + string(sqlite3_errmsg(db)));
        sqlite3_finalize(stmt);
        return false;
    }

    sqlite3_finalize(stmt);
    return true;
}

