// Function to block an IP address
void blockIP(const string& ip) {
    // This is a placeholder for the actual firewall blocking command
    // In a real implementation, you would use a system call to execute the appropriate firewall command
    cout << "Blocking IP address: " << ip << endl;
}

// Function to log blocked IP addresses
void logBlockedIP(const string& ip, const string& time) {
    ofstream logFile("blocked_ips.log", ios::app);
    if (logFile.is_open()) {
        logFile << time << " - " << ip << endl;
        logFile.close();
    } else {
        cerr << "Error opening log file!" << endl;
    }
}

// Function to parse input and block IP addresses
void parseAndBlockIPs(const vector<string>& ips) {
    for (const string& ip : ips) {
        // Validate IP address format
        if (isValidIP(ip)) {
            blockIP(ip);
            // Log the blocked IP address
            time_t now = time(0);
            char buffer[26];
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
            logBlockedIP(ip, string(buffer));
        } else {
            cerr << "Invalid IP address: " << ip << endl;
        }
    }
}

// Function to validate IP address format
bool isValidIP(const string& ip) {
    // This is a simple validation function that checks for basic IP address format
    // In a real implementation, you would use a more robust validation function
    if (ip.empty()) return false;
    for (char c : ip) {
        if (!isdigit(c) && c != '.' && c != '-') return false;
    }
    return true;
}

// Main function
int main() {
    vector<string> ips;
    string line;

    // Read IP addresses from input
    cout << "Enter IP addresses to block (one per line, press Enter to finish):" << endl;
    while (getline(cin, line)) {
        if (line.empty()) break;
        ips.push_back(line);
    }

    // Block IP addresses
    parseAndBlockIPs(ips);

    return 0;
}

