// Function to block traffic from a given IP address
void blockTraffic(const string& ip) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        cerr << "Error creating socket: " << strerror(errno) << endl;
        return;
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(0); // Listen on any port
    addr.sin_addr.s_addr = inet_addr(ip.c_str());

    if (bind(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        cerr << "Error binding socket: " << strerror(errno) << endl;
        close(sock);
        return;
    }

    if (listen(sock, 1) < 0) {
        cerr << "Error listening on socket: " << strerror(errno) << endl;
        close(sock);
        return;
    }

    // Accept incoming connections and block them
    while (true) {
        struct sockaddr_in clientAddr;
        socklen_t clientLen = sizeof(clientAddr);
        int clientSock = accept(sock, (struct sockaddr*)&clientAddr, &clientLen);

        if (clientSock < 0) {
            cerr << "Error accepting connection: " << strerror(errno) << endl;
            break;
        }

        // Close the client socket to block traffic
        close(clientSock);
    }

    close(sock);
}

