// Function to update block list from remote server
void updateBlockList(const string& serverUrl, const string& blockListFile) {
    CURL* curl = curl_easy_init();
    if (!curl) {
        cerr << "Failed to initialize cURL" << endl;
        return;
    }

    string url = serverUrl + "/blocklist.txt";
    ofstream file(blockListFile);

    if (!file.is_open()) {
        cerr << "Failed to open file for writing" << endl;
        curl_easy_cleanup(curl);
        return;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &file);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        cerr << "Error during cURL request: " << curl_easy_strerror(res) << endl;
    } else {
        cout << "Block list updated successfully from " << url << endl;
    }

    file.close();
    curl_easy_cleanup(curl);
}

// Callback function for cURL write operation
size_t writeCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ofstream* file = static_cast<ofstream*>(userp);
    file->write(static_cast<char*>(contents), size * nmemb);
    return size * nmemb;
}

// Function to check if an IP address is on the block list
bool isBlocked(const string& ip, const string& blockListFile) {
    ifstream file(blockListFile);
    string line;

    while (getline(file, line)) {
        if (line.find(ip) != string::npos) {
            return true;
        }
    }

    return false;
}

