// Function to read IP addresses from a file
vector<string> readIPAddresses(const string& filename) {
    vector<string> ipAddresses;
    ifstream file(filename);
    string line;
    while (getline(file, line)) {
        // Remove any leading/trailing whitespace
        line.erase(0, line.find_first_not_of(" \t"));
        line.erase(line.find_last_not_of(" \t") + 1);
        // Check if the line is not empty
        if (!line.empty()) {
            // Check if the line contains an IP address
            regex ipPattern("^([0-9]{1,3}\\.){3}[0-9]{1,3}$");
            if (regex_match(line, ipPattern)) {
                ipAddresses.push_back(line);
            }
        }
    }
    return ipAddresses;
}

// Function to write IP addresses to a file
void writeIPAddresses(const vector<string>& ipAddresses, const string& filename) {
    ofstream file(filename);
    for (const string& ip : ipAddresses) {
        file << ip << endl;
    }
}

