using namespace std;

// Function to check if an IP address is already blocked
bool isIPBlocked(const string& ip) {
    ifstream file("/etc/ufw.rules");
    string line;
    while (getline(file, line)) {
        if (line.find(ip) != string::npos) {
            return true;
        }
    }
    return false;
}

// Function to add a firewall rule for an IP address
void addIPBlock(const string& ip) {
    ofstream file("/etc/ufw.rules", ios::app);
    file << "ufw deny from " << ip << endl;
    file.close();
    cout << "IP address " << ip << " has been blocked." << endl;
}

// Function to block a list of IP addresses
void blockIPs(const vector<string>& ips) {
    for (const string& ip : ips) {
        if (isIPBlocked(ip)) {
            cout << "IP address " << ip << " is already blocked." << endl;
        } else {
            addIPBlock(ip);
        }
    }
}

// Main function
int main() {
    vector<string> ips;
    string ip;
    cout << "Enter IP addresses to block (one per line, press Enter to finish):" << endl;
    while (getline(cin, ip)) {
        if (ip.empty()) {
            break;
        }
        ips.push_back(ip);
    }
    blockIPs(ips);
    return 0;
}

