// Function to check if an IP address is in the given CIDR range
bool isIpInRange(const string& ip, const string& cidr) {
    // Parse the CIDR range
    size_t pos = cidr.find('/');
    if (pos == string::npos) {
        return false;
    }
    string network = cidr.substr(0, pos);
    int prefixLen = stoi(cidr.substr(pos + 1));

    // Convert IP address to long integer
    long ipLong = 0;
    stringstream ss(ip);
    string octet;
    while (getline(ss, octet, '.')) {
        ipLong = ipLong * 256 + stoi(octet);
    }

    // Convert network address to long integer
    long networkLong = 0;
    stringstream ss2(network);
    string octet2;
    while (getline(ss2, octet2, '.')) {
        networkLong = networkLong * 256 + stoi(octet2);
    }

    // Calculate the subnet mask
    long mask = 0;
    for (int i = 0; i < prefixLen; i++) {
        mask = mask | (1L << (32 - i - 1));
    }

    // Check if the IP address is in the network range
    return ((ipLong & mask) == (networkLong & mask));
}

