class KeyRotationManager {
private:
    std::string currentKey;
    std::string newKey;
    std::mutex keyMutex;
    bool rotationInProgress;
    std::thread rotationThread;

public:
    KeyRotationManager() : currentKey(""), newKey(""), rotationInProgress(false) {
        // Initialize with a random key
        RAND_bytes((unsigned char*)currentKey.data(), 32);
    }

    void startRotation() {
        if (rotationInProgress) return;
        rotationInProgress = true;
        rotationThread = std::thread(&KeyRotationManager::rotateKeys, this);
    }

    void stopRotation() {
        rotationInProgress = false;
        if (rotationThread.joinable()) {
            rotationThread.join();
        }
    }

    std::string getCurrentKey() {
        std::lock_guard<std::mutex> lock(keyMutex);
        return currentKey;
    }

    void rotateKeys() {
        std::this_thread::sleep_for(std::chrono::hours(24));
        std::lock_guard<std::mutex> lock(keyMutex);
        RAND_bytes((unsigned char*)newKey.data(), 32);
        std::swap(currentKey, newKey);
        std::cout << "Key rotation completed successfully." << std::endl;
    }

    void updateKey(const std::string& key) {
        std::lock_guard<std::mutex> lock(keyMutex);
        currentKey = key;
    }
};

int main() {
    KeyRotationManager manager;
    std::cout << "Current key: " << manager.getCurrentKey() << std::endl;

    manager.startRotation();

    std::this_thread::sleep_for(std::chrono::seconds(10));

    manager.stopRotation();

    return 0;
}

