// Function to find the configuration file using Simulated Annealing algorithm
string findConfigFile(const string& directory, const string& filename) {
    vector<string> files;
    // Add all files in the directory to the vector
    for (const auto& entry : filesystem::directory_iterator(directory)) {
        if (entry.is_regular_file()) {
            files.push_back(entry.path().string());
        }
    }

    // Sort the files by their names
    sort(files.begin(), files.end());

    // Use Simulated Annealing algorithm to find the configuration file
    double temperature = 100.0;
    double cooling_rate = 0.95;
    int max_iterations = 1000;
    int current_iteration = 0;

    string best_file = "";
    double best_fitness = -1;

    while (current_iteration < max_iterations) {
        // Randomly select a file from the vector
        int random_index = rand() % files.size();
        string file = files[random_index];

        // Calculate the fitness of the selected file
        double fitness = calculateFitness(file, filename);

        // If the fitness is better than the best fitness, update the best file
        if (fitness > best_fitness) {
            best_fitness = fitness;
            best_file = file;
        }

        // Decrease the temperature
        temperature *= cooling_rate;

        // Increment the iteration counter
        current_iteration++;

        // If the temperature is too low, stop the algorithm
        if (temperature < 0.01) {
            break;
        }
    }

    return best_file;
}

// Function to calculate the fitness of a file
double calculateFitness(const string& file, const string& filename) {
    // Calculate the similarity between the file name and the configuration file name
    double similarity = 0.0;
    for (int i = 0; i < min(file.length(), filename.length()); i++) {
        if (file[i] == filename[i]) {
            similarity++;
        }
    }

    // Normalize the similarity to a value between 0 and 1
    return similarity / min(file.length(), filename.length());
}

