import java.util.stream.Collectors;

public class AnomalyDetector {
    private final Map<String, Double> trafficStats = new ConcurrentHashMap<>();
    private final AtomicInteger blockedRequests = new AtomicInteger(0);
    private final double threshold = 2.0; // Adjust based on your environment
    private final List<String> suspiciousIPs = new ArrayList<>();

    public void analyzeTraffic(String ip, int port, String protocol, long bytes) {
        String key = ip + ":" + port + ":" + protocol;
        trafficStats.put(key, trafficStats.getOrDefault(key, 0.0) + bytes);

        double avg = trafficStats.values().stream().mapToDouble(Double::doubleValue).average().orElse(0.0);
        double stdDev = Math.sqrt(trafficStats.values().stream()
                .mapToDouble(Double::doubleValue)
                .map(x -> Math.pow(x - avg, 2))
                .average().orElse(0.0));

        if (stdDev > threshold) {
            suspiciousIPs.add(ip);
            blockedRequests.incrementAndGet();
            System.out.println("Blocked suspicious traffic from " + ip);
        }
    }

    public void printStats() {
        System.out.println("Blocked requests: " + blockedRequests.get());
        System.out.println("Suspicious IPs: " + suspiciousIPs);
    }
}

