import java.io.*;
import java.net.*;
import java.util.*;

public class DDoSBlocker {
    private static final String FIREWALL_RULE_FILE = "/etc/iptables/rules.v4";
    private static final String LOG_FILE = "/var/log/ddos-blocker.log";

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Usage: java DDoSBlocker <IP addresses>");
            return;
        }

        List<String> ipAddresses = Arrays.asList(args);
        updateFirewallRule(ipAddresses);
        logAccessAttempt();
    }

    private static void updateFirewallRule(List<String> ipAddresses) {
        try {
            File file = new File(FIREWALL_RULE_FILE);
            StringBuilder content = new StringBuilder();
            Scanner scanner = new Scanner(file);
            boolean ruleExists = false;

            while (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                if (line.contains("-A INPUT -s")) {
                    ruleExists = true;
                    break;
                }
                content.append(line).append("\n");
            }

            if (!ruleExists) {
                content.append("-A INPUT -s ").append(String.join(",", ipAddresses)).append(" -j DROP\n");
            } else {
                content.append("-A INPUT -s ").append(String.join(",", ipAddresses)).append(" -j DROP\n");
            }

            file.delete();
            PrintWriter writer = new PrintWriter(file);
            writer.print(content.toString());
            writer.close();
            System.out.println("Firewall rule updated successfully.");
        } catch (Exception e) {
            System.err.println("Error updating firewall rule: " + e.getMessage());
        }
    }

    private static void logAccessAttempt() {
        try {
            File file = new File(LOG_FILE);
            PrintWriter writer = new PrintWriter(file);
            writer.println("Access attempt detected at " + new Date());
            writer.close();
        } catch (Exception e) {
            System.err.println("Error logging access attempt: " + e.getMessage());
        }
    }
}

