import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class NetworkTrafficMonitor {

    private static final int PORT = 8080;
    private static final int BUFFER_SIZE = 1024;
    private DatagramSocket socket;
    private List<Rule> rules;
    private ExecutorService executorService;

    public NetworkTrafficMonitor() {
        this.rules = new ArrayList<>();
        this.executorService = Executors.newCachedThreadPool();
    }

    public void startMonitoring() throws IOException {
        socket = new DatagramSocket(PORT);
        executorService.submit(this::monitorTraffic);
    }

    private void monitorTraffic() {
        byte[] buffer = new byte[BUFFER_SIZE];
        DatagramPacket packet = new DatagramPacket(buffer, buffer.length);

        while (true) {
            try {
                socket.receive(packet);
                String data = new String(packet.getData(), 0, packet.getLength());
                System.out.println("Received packet: " + data);

                // Apply rules to the packet
                boolean isBlocked = applyRules(data);
                if (isBlocked) {
                    System.out.println("Blocking packet due to rule match.");
                    packet.setLength(0);
                } else {
                    System.out.println("Packet allowed.");
                }
            } catch (IOException e) {
                System.err.println("Error receiving packet: " + e.getMessage());
            }
        }
    }

    private boolean applyRules(String data) {
        for (Rule rule : rules) {
            if (rule.matches(data)) {
                return true;
            }
        }
        return false;
    }

    public void addRule(Rule rule) {
        rules.add(rule);
    }

    public void removeRule(Rule rule) {
        rules.remove(rule);
    }

    public void updateRules(List<Rule> newRules) {
        this.rules.clear();
        this.rules.addAll(newRules);
    }

